class FizzBuzz {
public:
  explicit FizzBuzz(int n);
  void fizz(std::function<void()> printFizz);
  void buzz(std::function<void()> printBuzz);
  void fizzbuzz(std::function<void()> printFizzBuzz);
  void number(std::function<void(int)> printNumber);
};

questions.modelAnswer:
#include <condition_variable>
#include <functional>
#include <mutex>

// Four threads call fizz(), buzz(), fizzbuzz() and number() once each.
// Together they must print 1..n in order; each thread prints only its own kind.
class FizzBuzz {
  int n_, cur_ = 1;                 // the next number to handle
  std::mutex m_;
  std::condition_variable cv_;

  // Each thread loops: wait until cur_ is "mine" or we are done, print, advance, wake all.
  void run(const std::function<bool(int)>& mine, const std::function<void(int)>& print) {
    std::unique_lock lk(m_);
    while (true) {
      cv_.wait(lk, [&] { return cur_ > n_ || mine(cur_); });
      if (cur_ > n_) return;        // everyone must be able to leave at the end
      print(cur_);
      ++cur_;
      cv_.notify_all();             // the next number may belong to any of the other 3
    }
  }
public:
  explicit FizzBuzz(int n) : n_(n) {}
  void fizz(std::function<void()> printFizz) {
    run([](int i) { return i % 3 == 0 && i % 5 != 0; }, [&](int) { printFizz(); });
  }
  void buzz(std::function<void()> printBuzz) {
    run([](int i) { return i % 5 == 0 && i % 3 != 0; }, [&](int) { printBuzz(); });
  }
  void fizzbuzz(std::function<void()> printFizzBuzz) {
    run([](int i) { return i % 15 == 0; }, [&](int) { printFizzBuzz(); });
  }
  void number(std::function<void(int)> printNumber) {
    run([](int i) { return i % 3 != 0 && i % 5 != 0; }, printNumber);
  }
};

