  void first(std::function<void()> printFirst);
  void second(std::function<void()> printSecond);
  void third(std::function<void()> printThird);
};

questions.modelAnswer:
#include <condition_variable>
#include <functional>
#include <mutex>

// Three threads call first(), second(), third() in any order and at any time.
// The prints must always come out first, second, third.
class Foo {
  std::mutex m_;
  std::condition_variable cv_;
  int stage_ = 1;                   // which call may run now; guarded by m_
public:
  void first(std::function<void()> printFirst) {
    std::lock_guard lk(m_);
    printFirst();
    stage_ = 2;
    cv_.notify_all();               // notify_all: both waiters share one cv
  }
  void second(std::function<void()> printSecond) {
    std::unique_lock lk(m_);
    cv_.wait(lk, [this] { return stage_ == 2; });   // predicate: no lost wakeup, no spurious run
    printSecond();
    stage_ = 3;
    cv_.notify_all();
  }
  void third(std::function<void()> printThird) {
    std::unique_lock lk(m_);
    cv_.wait(lk, [this] { return stage_ == 3; });
    printThird();
  }
};
